diff --git a/src/kernels/cuda/native_moe.cu b/src/kernels/cuda/native_moe.cu
index 456ab09c..83dac80d 100644
--- a/src/kernels/cuda/native_moe.cu
+++ b/src/kernels/cuda/native_moe.cu
@@ -95,6 +95,43 @@ __global__ void combine_k10_vec4(const float4* __restrict__ parts4, const float*
     sum.w += sh.w;
     output4[c4] = sum;
 }
+#if !defined(STRATA_USE_HIP) && !defined(STRATA_HIP_GFX906)
+// Scale-only fusion keeps the separately rounded shared product.
+__global__ void combine_k10_vec4_gated(const float4* __restrict__ parts4, const float* __restrict__ weights,
+                                 const float4* __restrict__ shared4, float4* __restrict__ output4,
+                                 int64_t n4, const float* sg) {
+    const int64_t tk = blockIdx.y;
+    parts4 += tk * 10 * n4;
+    weights += tk * 10;
+    shared4 += tk * n4;
+    output4 += tk * n4;
+    const int64_t c4 = int64_t(blockIdx.x) * blockDim.x + threadIdx.x;
+    if (c4 >= n4) return;
+    const float w0 = __ldg(weights + 0);
+    const float4 p0 = parts4[c4];
+    float4 sum = make_float4(p0.x * w0, p0.y * w0, p0.z * w0, p0.w * w0);
+#pragma unroll
+    for (int expert = 1; expert < 10; ++expert) {
+        const float w = __ldg(weights + expert);
+        const float4 p = parts4[int64_t(expert) * n4 + c4];
+        // the documented contract spelled out: the first product rounded, then one FMA per expert in order. Left to the
+        // compiler's contraction, a build may fuse a different product (gfx1151: the float4 kernel then differed from the
+        // scalar one, native_multi_parity)
+        sum.x = fmaf(p.x, w, sum.x);
+        sum.y = fmaf(p.y, w, sum.y);
+        sum.z = fmaf(p.z, w, sum.z);
+        sum.w = fmaf(p.w, w, sum.w);
+    }
+    float4 sh = shared4[c4];
+    const float gate = __fdividef(1.f, 1.f + __expf(-sg[tk]));
+    sh.x = __fmul_rn(sh.x, gate); sh.y = __fmul_rn(sh.y, gate); sh.z = __fmul_rn(sh.z, gate); sh.w = __fmul_rn(sh.w, gate);
+    sum.x += sh.x;
+    sum.y += sh.y;
+    sum.z += sh.z;
+    sum.w += sh.w;
+    output4[c4] = sum;
+}
+#endif
 bool valid_span(const void* p, size_t bytes) {
     const auto address = reinterpret_cast<uintptr_t>(p);
     return p && address % alignof(float) == 0 && bytes <= UINTPTR_MAX - address;
@@ -167,4 +204,26 @@ void native_moe_combine_multi_hits(const float* hits, const float* weights, cons
     const auto error = cudaGetLastError();
     if (error != cudaSuccess) throw std::runtime_error(cudaGetErrorString(error));
 }
+#if !defined(STRATA_USE_HIP) && !defined(STRATA_HIP_GFX906)
+
+void native_moe_combine_multi_gated(const float* parts, const float* weights, const float* shared,
+                                   const float* gate, float* output, int64_t n, int64_t k, int tokens, void* stream) {
+    if (!stream || n <= 0 || n > std::numeric_limits<int>::max() || (n & 3) || k != 10 || tokens < 1 || tokens > 8)
+        throw std::invalid_argument("scale-only combine requires aligned K10 rows and 1..8 tokens");
+    const size_t row = size_t(n) * tokens * sizeof(float), wb = size_t(k) * tokens * sizeof(float);
+    if (!valid_span(parts, row * k) || !valid_span(shared, row) || !valid_span(output, row) ||
+        !valid_span(weights, wb) || !valid_span(gate, size_t(tokens) * sizeof(float)) ||
+        ((uintptr_t(parts) | uintptr_t(shared) | uintptr_t(output)) & 15u) ||
+        overlap(output, row, parts, row * k) || overlap(output, row, shared, row) ||
+        overlap(output, row, weights, wb) || overlap(output, row, gate, size_t(tokens) * sizeof(float)))
+        throw std::invalid_argument("scale-only combine requires disjoint aligned output");
+    combine_k10_vec4_gated<<<dim3(unsigned((n / 4 + 127) / 128), unsigned(tokens)), 128, 0,
+                             static_cast<cudaStream_t>(stream)>>>(
+        reinterpret_cast<const float4*>(parts), weights, reinterpret_cast<const float4*>(shared),
+        reinterpret_cast<float4*>(output), n / 4, gate);
+    const auto error = cudaGetLastError();
+    if (error != cudaSuccess) throw std::runtime_error(cudaGetErrorString(error));
+}
+#endif
+
 }
